define_constants;
mpc = loadcase('case74ds');

% Set minimum voltage magnitude at bus 5 to 0.99 p.u.
bus5_idx = find(mpc.bus(:, BUS_I) == 5);
mpc.bus(bus5_idx, VMIN) = 0.99;

% Scale cubic cost coefficient (C3 term) of generators at bus 10 by 0
% This is implemented on the first cost coefficient (highest order) in gencost
if isfield(mpc, 'gencost')
    gen10_idx = find(mpc.gen(:, GEN_BUS) == 10);
    if ~isempty(gen10_idx)
        % Assuming polynomial cost functions with Cn in column NCOST+5 (first coeff)
        for k = 1:length(gen10_idx)
            gc_rows = find(mpc.gencost(:, 1) == 2 & mpc.gencost(:, 2) == gen10_idx(k)); %#ok<FNDSB>
            for r = gc_rows'
                ncost = mpc.gencost(r, NCOST);
                first_coeff_col = 5; % MATPOWER polynomial costs: coefficients start at col 5
                % Scale the highest-order (first) coefficient by 0
                mpc.gencost(r, first_coeff_col) = mpc.gencost(r, first_coeff_col) * 0;
            end
        end
    end
end

% Scale branch shunt susceptance BR_B between bus 14 and 70 by 1.2
branch_idx = find( ...
    (mpc.branch(:, F_BUS) == 14 & mpc.branch(:, T_BUS) == 70) | ...
    (mpc.branch(:, F_BUS) == 70 & mpc.branch(:, T_BUS) == 14) );
mpc.branch(branch_idx, BR_B) = mpc.branch(branch_idx, BR_B) * 1.2;

mpopt = mpoption('opf.violation', 1e-6);
results = runopf(mpc, mpopt);
printpf(results);

define_constants;
mpc = loadcase('case9');

% Scale quadratic cost coefficient (C3) for generators at bus 3
gen3_idx = find(mpc.gen(:, GEN_BUS) == 3);
mpc.gencost(gen3_idx, 5) = mpc.gencost(gen3_idx, 5) * 0.8;

mpopt = mpoption('opf.violation', 1e-6);
results = runopf(mpc, mpopt);
printpf(results);

define_constants;
mpc = loadcase('case33mg');

% Scale active power demand at bus 18 by 0.9
bus18_idx = find(mpc.bus(:, BUS_I) == 18);
mpc.bus(bus18_idx, PD) = mpc.bus(bus18_idx, PD) * 0.9;

% Set minimum reactive power output of generator at bus 1 to -50 MVAr
gen1_idx = find(mpc.gen(:, GEN_BUS) == 1);
mpc.gen(gen1_idx, QMIN) = -50;

% Scale branch resistance between bus 14 and bus 22 by 1.1
branch_idx = find((mpc.branch(:, F_BUS) == 14 & mpc.branch(:, T_BUS) == 22) | ...
                   (mpc.branch(:, F_BUS) == 22 & mpc.branch(:, T_BUS) == 14));
mpc.branch(branch_idx, BR_R) = mpc.branch(branch_idx, BR_R) * 1.1;

mpopt = mpoption('opf.violation', 1e-7);
results = runopf(mpc, mpopt);
printpf(results);

define_constants;
mpc = loadcase('case9Q');

% Scale reactive power demand at bus 2 by 1.1
bus2_idx = find(mpc.bus(:, BUS_I) == 2);
mpc.bus(bus2_idx, QD) = mpc.bus(bus2_idx, QD) * 1.1;

% Scale maximum voltage magnitude at bus 1 by 1.02
bus1_idx = find(mpc.bus(:, BUS_I) == 1);
mpc.bus(bus1_idx, VMAX) = mpc.bus(bus1_idx, VMAX) * 1.02;

% Set branch status to 1 for line between bus 6 and bus 4
branch_idx = find( ...
    (mpc.branch(:, F_BUS) == 6 & mpc.branch(:, T_BUS) == 4) | ...
    (mpc.branch(:, F_BUS) == 4 & mpc.branch(:, T_BUS) == 6) );
mpc.branch(branch_idx, BR_STATUS) = 1;

mpopt = mpoption('opf.violation', 1e-7);
results = runopf(mpc, mpopt);
printpf(results);

define_constants;
mpc = loadcase('case118');

% Scale maximum voltage magnitude at bus 59 by 1.05
bus59_idx = find(mpc.bus(:, BUS_I) == 59);
mpc.bus(bus59_idx, VMAX) = mpc.bus(bus59_idx, VMAX) * 1.05;

% Scale maximum reactive power output (QMAX) of generator at bus 12 by 1.2
gen12_idx = find(mpc.gen(:, GEN_BUS) == 12);
mpc.gen(gen12_idx, QMAX) = mpc.gen(gen12_idx, QMAX) * 1.2;

mpopt = mpoption('opf.violation', 1e-6);
results = runopf(mpc, mpopt);
printpf(results);
